import { useCallback } from 'react';

import OpenFin from '@openfin/core';

import { createDropdownMenuChannel } from '@common/utils/enterprise-channels';
import { getClosestBoundsIfModalBoundsOffscreen } from '@common/utils/modal-bounds';
import { DropdownMenuChannelMessage } from '@common/utils/popup-window';
import { WindowName } from '@common/utils/window';

import { DropdownMenu } from '@enterprise/components/App/ContextMenu/DropdownMenu';
import BrowserThemeProvider from '@enterprise/components/App/ThemeProvider/BrowserThemeProvider';

import { useIsWindows } from '@enterprise/hooks/useIsWindows';
import { useManagePopupWindow } from '@enterprise/hooks/useManagePopupWindow';

export const DropdownMenuPopup = () => {
    const isWindows = useIsWindows();

    const showPopupOverride = useCallback(async (bounds: OpenFin.Bounds) => {
        const window = fin.me as OpenFin.Window;
        await window.setBounds(await getClosestBoundsIfModalBoundsOffscreen(bounds));
        await window.bringToFront();
        await window.show();
        await window.focus();
    }, []);

    const { payload, showPopup, onResponse } = useManagePopupWindow<DropdownMenuChannelMessage>(
        WindowName.DropdownMenu,
        createDropdownMenuChannel,
        showPopupOverride,
        { dispatchDirectlyToChannel: true }
    );

    return (
        <BrowserThemeProvider>
            {payload && (
                <DropdownMenu
                    messageData={payload}
                    showPopup={showPopup}
                    onResponse={onResponse}
                    isWindows={isWindows}
                />
            )}
        </BrowserThemeProvider>
    );
};

export default DropdownMenuPopup;
